"""Fixed development bank across other previously inspected contracts, no local retuning."""
import os,json,sqlite3,hashlib,math
from pathlib import Path
import pandas as pd,numpy as np
from scalar_checks import independent_from_records
P=Path('/data/analysis/avzvol-focus');C=os.environ['FOCUS_CONTRACT'];R=P/C;bank=json.load(open(P/'frozen-replication-bank.json'));baseline=json.load(open(Path('/data/analysis/avzvol-longevity')/C/'manifest.json'));dates=baseline['event_dates'];di={d:i for i,d in enumerate(dates)};nd=len(dates);ev=json.load(open(R/'evidence.json'));critical=ev['approx_joint95_critical'];con=sqlite3.connect(R/'thinned-private.sqlite');rows=[]
for recipe in bank['recipes']:
 a=pd.read_sql_query('SELECT * FROM signals WHERE family=? AND landmark=? AND D=? AND q=? AND endpoint=?',con,params=(recipe['family'],recipe['landmark'],recipe['D'],recipe['q'],recipe['endpoint'])).to_dict('records');m=independent_from_records(a,recipe['condition'],di,nd);lo=(m['effect']-critical*m['se'])*100 if m['eligible'] and critical is not None else None;hi=(m['effect']+critical*m['se'])*100 if m['eligible'] and critical is not None else None
 if C=='MNQ_12-26':
  original=next(r for r in json.load(open(R/'candidate-review-evidence.json'))['candidates'] if r['review_priority'] and r['family']==recipe['family'] and r['landmark']==recipe['landmark'] and r['D']==recipe['D'] and r['q']==recipe['q'] and r['endpoint']==recipe['endpoint'] and r['condition_id']==recipe['condition_id']);assert np.isclose(m['effect']*100,original['matched_difference_points']) and np.isclose(lo,original['approx_joint95_lower_points'])
 rows.append(dict(recipe_id=recipe['recipe_id'],contract=C,family=recipe['family'],landmark=recipe['landmark'],D=recipe['D'],q=recipe['q'],endpoint=recipe['endpoint'],condition_id=recipe['condition_id'],real_resolved=m['real_resolved'],control_resolved=m['control_resolved'],matched_weight=m['matched_weight'],eligible=bool(m['eligible']),difference_points=100*m['effect'] if math.isfinite(m['effect']) else None,approx_within_contract_joint95_lower=lo,approx_within_contract_joint95_upper=hi,positive_lower_candidate=bool(lo is not None and lo>0),virgin_holdout=False,pnl_computed=False))
con.close();out=dict(status='FIXED_BANK_RECOUNT_COMPLETE',contract=C,recipes=len(rows),bank_sha256=hashlib.sha256((P/'frozen-replication-bank.json').read_bytes()).hexdigest(),not_retuned=True,selected_on_discovery_pilot=True,results=rows,uncertainty='same contract-wide exploratory max-statistic band; not a joint correction across all6contracts or earlier research; no causal interpretation');(R/'fixed-bank-evidence.json').write_text(json.dumps(out,indent=2,allow_nan=False)+'\n');pd.DataFrame(rows).to_csv(R/'fixed-bank-results.csv',index=False);print('FIXED_BANK',C,len(rows),sum(x['eligible'] for x in rows),sum(x['positive_lower_candidate'] for x in rows),flush=True)
